package android.app;import android.content.Context;import android.os.Bundle;import java.util.*;public class Application extends Context {public boolean attached;public List<ActivityLifecycleCallbacks> callbacks=new ArrayList<>();public Application(){app=this;}public void registerActivityLifecycleCallbacks(ActivityLifecycleCallbacks c){callbacks.add(c);}public void unregisterActivityLifecycleCallbacks(ActivityLifecycleCallbacks c){callbacks.remove(c);}public interface ActivityLifecycleCallbacks {void onActivityCreated(Activity a,Bundle b);void onActivityResumed(Activity a);void onActivityDestroyed(Activity a);void onActivityStarted(Activity a);void onActivityPaused(Activity a);void onActivityStopped(Activity a);void onActivitySaveInstanceState(Activity a,Bundle b);}}
